codeExamples.code:
let score = 0;
console.log(score);  // 0

score = 10;
console.log(score);  // 10

const playerName = "Alex";
console.log(playerName);  // Alex

let name = "Vishnu";          // string (text)
let age = 25;                   // number
let isStudent = true;           // boolean (true/false)

console.log(name);
console.log(age);
console.log(isStudent);

let temperature = 20;
console.log(temperature);  // 20

temperature = 25;
console.log(temperature);  // 25

temperature = temperature + 5;
console.log(temperature);  // 30

let firstName = "Vishnu";
let lastName = "Kumar";
let fullName = firstName + " " + lastName;
let isStudent = true;
let courseCount = 5;

console.log(fullName);      // Vishnu Kumar
console.log(courseCount);   // 5

if (true) {
  var message = "Hello";
}

console.log(message);  // "Hello" (accessible outside the block!)

// With var — all callbacks see the same final value
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 100);
}
// Output: 3, 3, 3

// With let — each callback sees its own value
for (let j = 0; j < 3; j++) {
  setTimeout(() => console.log(j), 100);
}
// Output: 0, 1, 2

// var allows redeclaration (dangerous!)
var x = 10;
var x = 20;
console.log(x);  // 20 — the first value is gone

// var is hoisted — you can use it before the declaration
console.log(name);  // undefined (no error!)
var name = "Vishnu";
console.log(name);  // "Vishnu"

const user = { name: "Alex", age: 25 };

// Mutation — this works!
user.age = 26;
user.city = "London";
console.log(user);  // { name: "Alex", age: 26, city: "London" }

// Reassignment — this fails!
// user = { name: "Sam" };
// TypeError: Assignment to constant variable.

const colors = ["red", "green"];

colors.push("blue");
console.log(colors);  // ["red", "green", "blue"]

colors[0] = "yellow";
console.log(colors);  // ["yellow", "green", "blue"]

// colors = ["a", "b"];
// TypeError: Assignment to constant variable.

const settings = Object.freeze({
  theme: "dark",
  fontSize: 14
});

settings.theme = "light";
console.log(settings.theme);  // "dark" (change was ignored)

settings.newProp = "hi";
console.log(settings.newProp);  // undefined (property not added)

const original = { name: "Alex", score: 100 };

// Instead of mutating:
// original.score = 150;

// Create a new object with the updated value:
const updated = { ...original, score: 150 };

console.log(original);  // { name: "Alex", score: 100 } — unchanged
console.log(updated);   // { name: "Alex", score: 150 }
